  `v_color_2` int(4) NOT NULL DEFAULT 0,
  `v_pos_x` float NOT NULL,
  `v_pos_y` float NOT NULL,
  `v_pos_z` float NOT NULL,
  `v_pos_a` float NOT NULL,
  `v_millage` float NOT NULL DEFAULT 0,
  `v_buydate` date NOT NULL,
  `v_engine_boost` float NOT NULL DEFAULT 0,
  `v_brake_boost` float NOT NULL DEFAULT 0,
  `v_stability_boost` float NOT NULL DEFAULT 0,
  `v_type` int(6) NOT NULL DEFAULT 0,
