  `v_sell_carmarket` int(6) NOT NULL DEFAULT 0,
  `v_gps_tracker` int(6) NOT NULL DEFAULT 0,
  `v_vw` int(6) NOT NULL DEFAULT 0,
  `v_int` int(6) NOT NULL DEFAULT 0,
  `v_paint` int(6) NOT NULL DEFAULT 3,
  `v_fine` int(6) NOT NULL DEFAULT 0,
  `c_toner` varchar(64) NOT NULL DEFAULT '0|0|0',
  `c_vinil` int(11) NOT NULL DEFAULT 0,
  `c_strobs` int(11) NOT NULL DEFAULT 0,
  `c_lights` varchar(64) NOT NULL DEFAULT '255|255|255',
